import React, { useState, useEffect } from "react";
import { InlineMath } from "react-katex";
import "katex/dist/katex.min.css";

// =====================================================
// MATH + LINE BREAK RENDERER
// =====================================================
function renderInlineMath(text) {
  if (text === null || text === undefined) return null;

  // Match $...$  OR  \(...\)  OR  \[...\]
  const regex = /(\$[^\$]+\$|\\\([\s\S]+?\\\)|\\\[[\s\S]+?\\\])/g;
  const parts = String(text).split(regex);

  return parts.map((part, index) => {
    if (!part) return null;

    if (part.startsWith("$") && part.endsWith("$") && part.length > 2) {
      return <InlineMath key={index} math={part.slice(1, -1)} />;
    }
    if (part.startsWith("\\(") && part.endsWith("\\)") && part.length > 4) {
      return <InlineMath key={index} math={part.slice(2, -2)} />;
    }
    if (part.startsWith("\\[") && part.endsWith("\\]") && part.length > 4) {
      return <InlineMath key={index} math={part.slice(2, -2)} />;
    }
    return <React.Fragment key={index}>{part}</React.Fragment>;
  });
}

function MathText({ text }) {
  if (text === null || text === undefined) return null;

  // Normalize legacy \(...\) \[...\] → $...$
  const normalized = String(text)
    .replace(/\\\(/g, "$")
    .replace(/\\\)/g, "$")
    .replace(/\\\[/g, "$")
    .replace(/\\\]/g, "$");

  const lines = normalized.split("\n");

  return (
    <span className="math-text">
      {lines.map((line, index) => (
        <React.Fragment key={index}>
          {renderInlineMath(line)}
          {index < lines.length - 1 && <br />}
        </React.Fragment>
      ))}
    </span>
  );
}

/**
 * QuestionText: detects "Read the following passage" and renders
 * the passage portion in a highlighted box.
 */
function QuestionText({ text }) {
  if (!text) return null;

  const marker = "Read the following passage";
  const idx = text.indexOf(marker);

  if (idx === -1) {
    return <MathText text={text} />;
  }

  const questionPart = text.slice(0, idx).trim();
  const passagePart = text.slice(idx).trim();

  return (
    <>
      {questionPart && (
        <div style={{ marginBottom: "12px", fontWeight: "600" }}>
          <MathText text={questionPart} />
        </div>
      )}
      <div
        style={{
          background: "#fffbeb",
          borderLeft: "4px solid #f59e0b",
          padding: "12px 14px",
          borderRadius: "8px",
          fontStyle: "italic",
          color: "#4a3f1e",
          fontSize: "14px",
          lineHeight: "1.8",
          fontWeight: "400",
        }}
      >
        <MathText text={passagePart} />
      </div>
    </>
  );
}

