    question: "According to the passage, what is one of the main objectives of the NEP?\nRead the passage and answer the following question:\nThe National Education Policy (NEP) 2020 is among the most important education reforms introduced in India in recent years. It seeks to improve the education system by making it more holistic, flexible, multidisciplinary, and better suited to the demands of the 21st century. To achieve this, the policy replaces the 10+2 pattern with a 5+3+3+4 structure, giving special importance to the foundational stage and promoting critical thinking from an early age.\nA major feature of the NEP is its focus on using the mother tongue or regional language as the medium of instruction at the primary level. This has drawn both support and concern. Many experts feel it can strengthen children’s roots and understanding, while others worry about practical challenges in implementation and possible effects on English language proficiency.\nIn addition, the NEP encourages vocational education, digital literacy, and interdisciplinary studies. It aims to move away from rote learning and an exam-centred approach by promoting practical knowledge and creativity. If carried out effectively, the NEP could significantly reshape India’s educational landscape for future generations.",
